mapper.sql:
WHERE c.status <> 'DELETED'

AND c.phone_hash = #{phoneHash}
AND c.name ILIKE #{namePattern}
AND c.preferred_language = #{language}
AND c.status = #{status}
AND coalesce(c.last_visit_at, c.registered_at) < #{inactiveBefore}
AND (c.registered_at AT TIME ZONE #{timezone})::date >= #{registeredFrom}
AND (c.registered_at AT TIME ZONE #{timezone})::date <= #{registeredTo}

mapper.select:



ORDER BY ${orderBy} DESCASC NULLS LAST,
         c.id
LIMIT #{limit} OFFSET #{offset}
